class Solution {
    public int countMatchingPairs(int[][] grid) {
        int n = grid.length, total = 0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int k = 0;
                while (k < n && grid[r][k] == grid[k][c]) k++;
                if (k == n) total++;
            }
        }
        return total;
    }
}

