from bisect import bisect_left, bisect_right

class Solution:
    def countMatchingPairs(self, grid: List[List[int]]) -> int:
        rows = sorted(tuple(r) for r in grid)
        total = 0
        for col in zip(*grid):
            total += bisect_right(rows, col) - bisect_left(rows, col)
        return total

