class Solution {
    public int countMatchingPairs(int[][] grid) {
        int n = grid.length;
        int[][] rows = grid.clone();
        Arrays.sort(rows, Arrays::compare);
        int total = 0;
        int[] col = new int[n];
        for (int c = 0; c < n; c++) {
            for (int k = 0; k < n; k++) col[k] = grid[k][c];
            total += bound(rows, col, true) - bound(rows, col, false);
        }
        return total;
    }

    // First row > col (upper) or >= col (lower).
    private int bound(int[][] rows, int[] col, boolean upper) {
        int lo = 0, hi = rows.length;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            int c = Arrays.compare(rows[mid], col);
            if (c < 0 || (upper && c == 0)) lo = mid + 1; else hi = mid;
        }
        return lo;
    }
}

