class Solution {
public:
    int countMatchingPairs(vector<vector<int>>& grid) {
        int n = grid.size();
        vector<vector<int>> rows = grid;
        sort(rows.begin(), rows.end());
        int total = 0;
        vector<int> col(n);
        for (int c = 0; c < n; c++) {
            for (int k = 0; k < n; k++) col[k] = grid[k][c];
            auto [lo, hi] = equal_range(rows.begin(), rows.end(), col);
            total += hi - lo;
        }
        return total;
    }
};

