static int gN;

static int cmpSeq(const int* a, const int* b) {
    for (int k = 0; k < gN; k++) if (a[k] != b[k]) return a[k] < b[k] ? -1 : 1;
    return 0;
}

static int cmpRow(const void* a, const void* b) {
    return cmpSeq(*(int* const*) a, *(int* const*) b);
}

// First row > col (upper) or >= col (lower).
static int bound(int** rows, int n, const int* col, bool upper) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        int c = cmpSeq(rows[mid], col);
        if (c < 0 || (upper && c == 0)) lo = mid + 1; else hi = mid;
    }
    return lo;
}

int countMatchingPairs(int** grid, int gridSize, int* gridColSize) {
    int n = gridSize;
    gN = n;
    int** rows = malloc(n * sizeof(int*));
    memcpy(rows, grid, n * sizeof(int*));
    qsort(rows, n, sizeof(int*), cmpRow);
    int total = 0;
    int* col = malloc(n * sizeof(int));
    for (int c = 0; c < n; c++) {
        for (int k = 0; k < n; k++) col[k] = grid[k][c];
        total += bound(rows, n, col, true) - bound(rows, n, col, false);
    }
    free(rows);
    free(col);
    return total;
}

