class Solution {
    public int countMatchingPairs(int[][] grid) {
        int n = grid.length;
        Map<List<Integer>, Integer> rows = new HashMap<>();
        for (int[] r : grid) {
            List<Integer> key = new ArrayList<>(n);
            for (int v : r) key.add(v);
            rows.merge(key, 1, Integer::sum);
        }
        int total = 0;
        for (int c = 0; c < n; c++) {
            List<Integer> col = new ArrayList<>(n);
            for (int k = 0; k < n; k++) col.add(grid[k][c]);
            total += rows.getOrDefault(col, 0);
        }
        return total;
    }
}

