struct SeqHash {
    size_t operator()(const vector<int>& v) const {
        size_t h = v.size();
        for (int x : v) h ^= x + 0x9e3779b97f4a7c15ULL + (h << 6) + (h >> 2);
        return h;
    }
};

class Solution {
public:
    int countMatchingPairs(vector<vector<int>>& grid) {
        int n = grid.size();
        unordered_map<vector<int>, int, SeqHash> rows;
        for (auto& r : grid) rows[r]++;
        int total = 0;
        vector<int> col(n);
        for (int c = 0; c < n; c++) {
            for (int k = 0; k < n; k++) col[k] = grid[k][c];
            auto it = rows.find(col);
            if (it != rows.end()) total += it->second;
        }
        return total;
    }
};

