static unsigned long long hashSeq(int** g, int n, int fixed, bool isRow) {
    unsigned long long h = 1469598103934665603ULL;
    for (int k = 0; k < n; k++) {
        int v = isRow ? g[fixed][k] : g[k][fixed];
        h = (h ^ (unsigned) v) * 1099511628211ULL;
    }
    return h;
}

int countMatchingPairs(int** grid, int gridSize, int* gridColSize) {
    int n = gridSize;
    unsigned cap = 1;
    while (cap < 2u * n) cap <<= 1;
    int* rep = malloc(cap * sizeof(int));
    int* count = calloc(cap, sizeof(int));
    unsigned long long* hs = malloc(cap * sizeof(unsigned long long));
    for (unsigned s = 0; s < cap; s++) rep[s] = -1;
    for (int r = 0; r < n; r++) {
        unsigned long long h = hashSeq(grid, n, r, true);
        unsigned s = (unsigned) (h >> 32) & (cap - 1);
        while (rep[s] != -1 && !(hs[s] == h && memcmp(grid[rep[s]], grid[r], n * sizeof(int)) == 0)) s = (s + 1) & (cap - 1);
        if (rep[s] == -1) { rep[s] = r; hs[s] = h; }
        count[s]++;
    }
    int total = 0;
    for (int c = 0; c < n; c++) {
        unsigned long long h = hashSeq(grid, n, c, false);
        for (unsigned s = (unsigned) (h >> 32) & (cap - 1); rep[s] != -1; s = (s + 1) & (cap - 1)) {
            if (hs[s] != h) continue;
            int k = 0;
            while (k < n && grid[rep[s]][k] == grid[k][c]) k++;
            if (k == n) { total += count[s]; break; }
        }
    }
    free(rep);
    free(count);
    free(hs);
    return total;
}
